PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS businesses (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, industry TEXT, employee_count INTEGER, description TEXT, improvement_areas TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS business_tools (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, tool_name TEXT NOT NULL, category TEXT DEFAULT 'Other');
CREATE TABLE IF NOT EXISTS workflows (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT DEFAULT '', frequency TEXT DEFAULT 'weekly', estimated_time REAL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, status TEXT DEFAULT 'complete', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS findings (id INTEGER PRIMARY KEY, assessment_id INTEGER NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL, impact TEXT NOT NULL, priority TEXT NOT NULL, confidence INTEGER NOT NULL, suggested_improvement TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recommendations (id INTEGER PRIMARY KEY, finding_id INTEGER NOT NULL REFERENCES findings(id) ON DELETE CASCADE, tool_key TEXT NOT NULL, tool_name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, reason TEXT NOT NULL, benefits TEXT NOT NULL, limitations TEXT NOT NULL, official_url TEXT NOT NULL, pricing_information TEXT NOT NULL, implementation_difficulty TEXT NOT NULL, selected INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS implementation_plans (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, recommendation_id INTEGER NOT NULL REFERENCES recommendations(id), title TEXT NOT NULL, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS implementation_tasks (id INTEGER PRIMARY KEY, plan_id INTEGER NOT NULL REFERENCES implementation_plans(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT DEFAULT '', assigned_to TEXT DEFAULT '', due_date TEXT, status TEXT DEFAULT 'todo', notes TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS adoption_records (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, plan_id INTEGER NOT NULL REFERENCES implementation_plans(id) ON DELETE CASCADE, team_members_total INTEGER DEFAULT 0, team_members_adopting INTEGER DEFAULT 0, reported_time_saved REAL DEFAULT 0, reported_improvement TEXT DEFAULT '', blockers TEXT DEFAULT '', notes TEXT DEFAULT '', recorded_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(plan_id));
CREATE TABLE IF NOT EXISTS feedback (id INTEGER PRIMARY KEY, category TEXT NOT NULL, message TEXT NOT NULL, contact_email TEXT DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS oauth_accounts (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider TEXT NOT NULL, provider_user_id TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, UNIQUE(provider, provider_user_id));
CREATE TABLE IF NOT EXISTS github_installations (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, installation_id INTEGER NOT NULL, account_login TEXT DEFAULT '', updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS github_connections (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, repo_id INTEGER NOT NULL, full_name TEXT NOT NULL, repo_url TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_business_owner ON businesses(owner_id);
CREATE INDEX IF NOT EXISTS idx_findings_assessment ON findings(assessment_id);
CREATE INDEX IF NOT EXISTS idx_plans_business ON implementation_plans(business_id);
